cypress_script:
describe('Web Tables CRUD Operations', () => {
  it('should add a new record successfully', () => {
    cy.visit('https://demoqa.com/webtables');
    cy.get('#addNewRecordButton').click();
    // Assuming there are inputs to fill in, add code to fill them in here
    cy.get('#submit').click(); // Assuming a submit button with id 'submit'
    cy.url().should('include', '/webtables');
    cy.get('table').should('contain', 'New Record Name'); // Check if the new record is listed
  });
  it('should not add a record with empty fields', () => {
    cy.visit('https://demoqa.com/webtables');
    cy.get('#addNewRecordButton').click();
    cy.get('#submit').click(); // Submit without filling any fields
    cy.url().should('include', '/webtables');
    cy.get('table').should('not.contain', ''); // Check that no new empty record is added
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Web Tables CRUD Operations', () => {
  test('should add a new record successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/webtables');
    await page.click('#addNewRecordButton');
    // Assuming there are inputs to fill in, add code to fill them in here
    await page.click('#submit'); // Assuming a submit button with id 'submit'
    await expect(page).toHaveURL(/.*webtables/);
    await expect(page.locator('table')).toContainText('New Record Name'); // Check if the new record is listed
  });
  test('should not add a record with empty fields', async ({ page }) => {
    await page.goto('https://demoqa.com/webtables');
    await page.click('#addNewRecordButton');
    await page.click('#submit'); // Submit without filling any fields
    await expect(page).toHaveURL(/.*webtables/);
    await expect(page.locator('table')).not.toContainText(''); // Check that no new empty record is added
  });
});
